246	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
247	    @Override
248	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
249	        Owner owner = this.clinicService.findOwnerById(ownerId);
250	        if (owner != null) {
251	            Pet pet = owner.getPet(petId);
252	            if (pet != null) {
253	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
254	            }
255	        }
256	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
257	    }
258	
259	    /**
260	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
261	     * derived from server-side state rather than stored columns (currently the
262	     * {@code bulkSignupWarning} flag). Both the create endpoint and the single-owner read endpoint
263	     * return their owner through this method, so an owner is decorated identically on either path
264	     * and each derived field is computed in exactly one place.
265	     *
266	     * @param owner the persisted owner to represent
267	     * @return the owner DTO with its derived read-only fields populated
268	     */
269	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
270	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
271	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
272	        return ownerDto;
273	    }
274	
275	    /**
276	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
277	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
278	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
279	     * blank (e.g. {@code "   "}). The offending field names are reported through an
280	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
281	     * as a 400 response carrying an {@code errors} array of field names.
282	     *
283	     * @param ownerFieldsDto the submitted owner fields
284	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
285	     */
286	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
287	        List<String> blankFields = new ArrayList<>();
288	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
289	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
290	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
291	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
292	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
293	        if (!blankFields.isEmpty()) {
294	            throw new InvalidOwnerFieldsException(blankFields);
295	        }
296	    }
297	
298	    private void addIfBlank(List<String> blankFields, String field, String value) {
299	        if (value != null && value.isBlank()) {
300	            blankFields.add(field);
301	        }
302	    }
303	
304	    /**
305	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
306	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
307	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
308	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
309	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
310	     *
311	     * @param city the city of the owner being created
312	     * @param lastName the last name of the owner being created
313	     * @return the formatted customer code
314	     */
315	    private String nextCustomerCode(String city, String lastName) {
316	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
317	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
318	        long sequence = ownersInCity(city) + 1L;
319	        return String.format("%s-%s-%04d", city3, last3, sequence);
320	    }
321	
322	    /**
323	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
324	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
325	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
326	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
327	     * new owner and surfaced as the read-only {@code namesakeCount} field.
328	     *
329	     * @param firstName the first name of the owner being created
330	     * @param lastName the last name of the owner being created
331	     * @return the number of existing owners with the same first and last name (case-insensitive)
332	     */
333	    private int namesakeCount(String firstName, String lastName) {
334	        return (int) this.clinicService.findAllOwners().stream()
335	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
336	                && equalsIgnoreCase(owner.getLastName(), lastName))
337	            .count();
338	    }
339	
340	    private boolean equalsIgnoreCase(String a, String b) {
341	        return a == null ? b == null : a.equalsIgnoreCase(b);
342	    }
343	
344	    /**
345	     * The maximum number of owners a single city may contain. Once a city already holds this many
346	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
347	     */
348	    private static final long MAX_OWNERS_PER_CITY = 50L;
349	
350	    /**
351	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
352	     * owners. Existing owners are matched to the requested city case-insensitively (using
353	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
354	     * the per-city counting used for the customer code. A city at capacity is reported through an
355	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
356	     * 409 Conflict response.
357	     *
358	     * @param city the city of the owner being created
359	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
360	     */
361	    private void rejectCityAtCapacity(String city) {
362	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
363	            throw new OwnerCityAtCapacityException(city);
364	        }
365	    }
366	
367	    /**
368	     * Counts the existing owners whose {@code city} matches the given city, compared
369	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Shared by the per-city
370	     * customer-code sequence ({@link #nextCustomerCode(String, String)}) and the per-city capacity
371	     * check ({@link #rejectCityAtCapacity(String)}) so both count a city's owners identically.
372	     *
373	     * @param city the city to count owners for
374	     * @return the number of existing owners in that city
375	     */
376	    private long ownersInCity(String city) {
377	        return this.clinicService.findAllOwners().stream()
378	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
379	            .count();
380	    }
381	
382	    /**
383	     * The maximum number of owners that may be registered on a single day. Once this many owners
384	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
385	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
386	     */
387	    private static final long MAX_OWNERS_PER_DAY = 100L;
388	
389	    /**
390	     * Resolves the effective registration date for a create request: the value supplied in the
391	     * request when present, otherwise the server's current date. The result is the raw effective
392	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
393	     *
394	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
395	     * @return the supplied date, or today when none was supplied
396	     */
397	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
398	        return suppliedDate != null ? suppliedDate : LocalDate.now();
399	    }
400	
401	    /**
402	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
403	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
404	     * the effective registration date so that a weekend value - whether supplied in the request or
405	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
406	     * registration date (such as the membership number's year segment and the daily create-limit
407	     * bucket) uses the adjusted business day.
408	     *
409	     * @param date the effective registration date
410	     * @return the same date when it is a weekday, otherwise the next Monday
411	     */
412	    private LocalDate businessDay(LocalDate date) {
413	        DayOfWeek dayOfWeek = date.getDayOfWeek();
414	        if (dayOfWeek == DayOfWeek.SATURDAY) {
415	            return date.plusDays(2);
416	        }
417	        if (dayOfWeek == DayOfWeek.SUNDAY) {
418	            return date.plusDays(1);
419	        }
420	        return date;
421	    }
422	
423	    /**
424	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
425	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
426	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
427	     * renders as a 429 Too Many Requests response.
428	     *
429	     * @param date the registration date of the owner being created (today)
430	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
431	     */
432	    private void rejectDailyRegistrationLimit(LocalDate date) {
433	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
434	            throw new DailyOwnerRegistrationLimitException(date);
435	        }
436	    }
437	
438	    /**
439	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
440	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
441	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
442	     * day's owners identically.
443	     *
444	     * @param date the registration date to count owners for
445	     * @return the number of existing owners registered on that day
446	     */
447	    private long ownersRegisteredOn(LocalDate date) {
448	        return this.clinicService.findAllOwners().stream()
449	            .filter(owner -> date.equals(owner.getRegistrationDate()))
450	            .count();
451	    }
452	
453	    /**
454	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
455	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
456	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
457	     */
458	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
459	
460	    /**
461	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
462	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
463	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
464	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
465	     * without a registration date, such as seed data) is never flagged.
466	     *
467	     * @param date the owner's registration date (the day it was created), or {@code null}
468	     * @return {@code true} if the day already holds more than the warning threshold of owners
469	     */
470	    private boolean bulkSignupWarning(LocalDate date) {
471	        if (date == null) {
472	            return false;
473	        }
474	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
475	    }
476	
477	    /**
478	     * Rejects a create request whose normalized telephone is already used by any existing owner.
479	     * Existing owners' telephones are reduced to the same canonical form (via
480	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
481	     * only in formatting still collide. A collision is reported through a
482	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
483	     * as a 409 Conflict response.
484	     *
485	     * @param normalizedTelephone the canonical telephone of the owner being created
486	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
487	     */
488	    private void rejectDuplicateTelephone(String normalizedTelephone) {
489	        boolean duplicate = existingOwnerMatches(
490	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
491	            normalizedTelephone);
492	        if (duplicate) {
493	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
494	        }
495	    }
496	
497	    /**
498	     * Rejects a create request whose normalized (lower-cased) email is already used by any existing
499	     * owner. Existing owners' emails are reduced to the same canonical form (via
500	     * {@link EmailNormalizer#normalize(String)}, i.e. lower-cased) before comparison, so addresses
501	     * that differ only in casing still collide. Owners without an email are ignored, and a request
502	     * without an email is never rejected. A collision is reported through a
503	     * {@link DuplicateOwnerEmailException}, which the {@code ExceptionControllerAdvice} renders as a
504	     * 409 Conflict response.
505	     *
506	     * @param normalizedEmail the canonical (lower-cased) email of the owner being created, or
507	     * {@code null} when none was supplied
508	     * @throws DuplicateOwnerEmailException if another owner already uses this email
509	     */
510	    private void rejectDuplicateEmail(String normalizedEmail) {
511	        if (normalizedEmail == null) {
512	            return;
513	        }
514	        boolean duplicate = existingOwnerMatches(
515	            owner -> emailNormalizer.normalize(owner.getEmail()),
516	            normalizedEmail);
517	        if (duplicate) {
518	            throw new DuplicateOwnerEmailException(normalizedEmail);
519	        }
520	    }
521	
522	    /**
523	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
524	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
525	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
526	     * and the owner being created to the same canonical key and reject a match.
527	     *
528	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
529	     * @param key the canonical key of the owner being created
530	     * @return {@code true} if some existing owner shares the key
531	     */
532	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
533	        return this.clinicService.findAllOwners().stream()
534	            .map(keyExtractor)
535	            .filter(Objects::nonNull)
536	            .anyMatch(key::equals);
537	    }
538	
539	    /**
540	     * Rejects a create request that shares a household with an existing owner: another owner already
541	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
542	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
543	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
544	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
545	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
546	     * check when the request opts in via {@code sharesHousehold}.
547	     *
548	     * @param lastName the last name of the owner being created
549	     * @param address the address of the owner being created
550	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
551	     */
552	    private void rejectDuplicateHousehold(String lastName, String address) {
553	        String canonicalLastName = canonicalizeHousehold(lastName);
554	        String canonicalAddress = canonicalizeHousehold(address);
555	        String key = householdKey(lastName, address);
556	        if (key == null) {
557	            return;
558	        }
559	        boolean duplicate = existingOwnerMatches(
560	            owner -> householdKey(owner.getLastName(), owner.getAddress()), key);
561	        if (duplicate) {
562	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
563	        }
564	    }
565	
566	    /**
567	     * Delimiter joining the canonical household fields into a single comparison key. A run of
568	     * whitespace is collapsed to a single space by {@link #canonicalizeHousehold(String)}, so this
569	     * newline can never occur inside a canonical value and the two fields cannot bleed into one
570	     * another across the join.
571	     */
572	    private static final String HOUSEHOLD_KEY_DELIMITER = "\n";
573	
574	    /**
575	     * Reduces an owner's household fields ({@code lastName} and {@code address}) to a single
576	     * canonical comparison key - the two canonical fields (see {@link #canonicalizeHousehold(String)})
577	     * joined by {@link #HOUSEHOLD_KEY_DELIMITER} - or {@code null} when either field is absent. Two
578	     * owners share a household exactly when their household keys are equal, so
579	     * {@link #rejectDuplicateHousehold(String, String)} can detect a collision by comparing this one
580	     * key through {@link #existingOwnerMatches(Function, String)} rather than the two fields separately.
581	     *
582	     * @param lastName the owner's last name, or {@code null}
583	     * @param address the owner's address, or {@code null}
584	     * @return the canonical household key, or {@code null} when either field is {@code null}
585	     */
586	    private String householdKey(String lastName, String address) {
587	        String canonicalLastName = canonicalizeHousehold(lastName);
588	        String canonicalAddress = canonicalizeHousehold(address);
589	        if (canonicalLastName == null || canonicalAddress == null) {
590	            return null;
591	        }
592	        return canonicalLastName + HOUSEHOLD_KEY_DELIMITER + canonicalAddress;
593	    }
594	
595	    /**
596	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
597	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
598	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
599	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
600	     *
601	     * @param value the raw field value, or {@code null}
602	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
603	     */
604	    private String canonicalizeHousehold(String value) {
605	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
606	    }
607	
608	    /**
609	     * Derives the stable, shared {@code householdId} for an owner joining a household via
610	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
611	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
612	     * owner with the same last name at the same address - regardless of casing or spacing - is
613	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
614	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
615	     *
616	     * @param lastName the last name of the owner being created
617	     * @param address the address of the owner being created
618	     * @return the shared household identifier
619	     */
620	    private String householdId(String lastName, String address) {
621	        String key = canonicalizeHousehold(lastName) + HOUSEHOLD_KEY_DELIMITER + canonicalizeHousehold(address);
622	        try {
623	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
624	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
625	            StringBuilder sb = new StringBuilder(digest.length * 2);
626	            for (byte b : digest) {
627	                sb.append(String.format("%02X", b));
628	            }
629	            return sb.substring(0, 16);
630	        } catch (java.security.NoSuchAlgorithmException e) {
631	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
632	        }
633	    }
634	}
