     1	package org.springframework.samples.petclinic.rest.validation;
     2	
     3	import java.util.List;
     4	import java.util.Map;
     5	
     6	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
     7	import org.springframework.stereotype.Component;
     8	
     9	/**
    10	 * Normalizes owner telephone numbers into the single canonical E.164 form that is stored, returned
    11	 * and compared for duplicates. Keeping this logic in one place lets the create endpoint treat a
    12	 * telephone as an opaque, already-canonical value: it {@link #normalize(String) normalizes} an
    13	 * incoming number once, then relies on {@link #canonicalize(String)} to compare it against
    14	 * existing owners regardless of how those numbers were originally formatted.
    15	 */
    16	@Component
    17	public class TelephoneNormalizer {
    18	
    19	    /** Assumed country code (with '+') for numbers submitted without an explicit country code. */
    20	    private static final String DEFAULT_COUNTRY_CODE = "+61";
    21	
    22	    /** Minimum number of digits after the leading '+' for a valid E.164 number. */
    23	    private static final int MIN_DIGITS = 8;
    24	
    25	    /** Maximum number of digits after the leading '+' for a valid E.164 number. */
    26	    private static final int MAX_DIGITS = 15;
    27	
    28	    /**
    29	     * Required number of national-significant digits (the digits after the country code) for each
    30	     * recognised country calling code. The Australian code {@code +61} carries 9 national digits and
    31	     * the North American {@code +1} carries 10; a number whose country code appears here but whose
    32	     * national portion has the wrong length is rejected. Codes not listed only face the generic
    33	     * {@code MIN_DIGITS}/{@code MAX_DIGITS} bound.
    34	     */
    35	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY_CODE = Map.of(
    36	        "61", 9,
    37	        "1", 10);
    38	
    39	    /**
    40	     * Normalizes a telephone number submitted to the create endpoint into E.164 form: a leading
    41	     * '+' and country code are kept when present, otherwise the country code {@code +61} is assumed
    42	     * and a single leading '0' is dropped from the national digits; spaces, dashes and brackets are
    43	     * stripped. The result must carry 8 to 15 digits after the '+'; additionally, for a recognised
    44	     * country calling code the national-significant part must have exactly the length that code
    45	     * requires ({@code +61} => 9 national digits, {@code +1} => 10). A value that fails any of these
    46	     * rules is rejected as a 400 (via {@link InvalidOwnerFieldsException}, which the
    47	     * {@code ExceptionControllerAdvice} renders with {@code telephone} in its {@code errors} array).
    48	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
    49	     *
    50	     * @param telephone the raw telephone value from the request
    51	     * @return the canonical E.164 telephone to store and return
    52	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
    53	     */
    54	    public String normalize(String telephone) {
    55	        String e164 = canonicalize(telephone);
    56	        int digitCount = e164.length() - 1;
    57	        if (!e164.startsWith("+") || digitCount < MIN_DIGITS || digitCount > MAX_DIGITS
    58	                || !hasValidNationalLength(e164)) {
    59	            throw new InvalidOwnerFieldsException(List.of("telephone"));
    60	        }
    61	        return e164;
    62	    }
    63	
    64	    /**
    65	     * Checks the national-significant length of a canonical E.164 number against the requirement for
    66	     * its country calling code. Numbers whose code is not one of the recognised codes pass this check
    67	     * (they are only bound by the generic digit-count range).
    68	     *
    69	     * @param e164 a canonical E.164 number (leading '+' followed by the country code and national digits)
    70	     * @return {@code true} if the national-number length matches the country code's requirement, or the
    71	     *         country code is not recognised
    72	     */
    73	    private boolean hasValidNationalLength(String e164) {
    74	        String digits = e164.substring(1);
    75	        for (Map.Entry<String, Integer> entry : NATIONAL_DIGITS_BY_COUNTRY_CODE.entrySet()) {
    76	            String countryCode = entry.getKey();
    77	            if (digits.startsWith(countryCode)) {
    78	                int nationalLength = digits.length() - countryCode.length();
    79	                return nationalLength == entry.getValue();
    80	            }
    81	        }
    82	        return true;
    83	    }
    84	
    85	    /**
    86	     * Reduces an arbitrary telephone (possibly {@code null} or differently formatted) to the
    87	     * canonical E.164 comparison form, so numbers that differ only in formatting still collide.
    88	     * A leading '+' and country code are kept when present; otherwise the country code {@code +61}
    89	     * is assumed and a single leading '0' is dropped from the national digits. Spaces, dashes,
    90	     * brackets and any other non-digit characters are stripped. Unlike {@link #normalize(String)}
    91	     * this never rejects its input (it does not enforce the digit-count rule); it is applied to
    92	     * existing owners' stored telephones during duplicate detection.
    93	     *
    94	     * @param telephone a stored or submitted telephone, or {@code null}
    95	     * @return the telephone reduced to its canonical E.164 comparison form
    96	     */
    97	    public String canonicalize(String telephone) {
    98	        if (telephone == null) {
    99	            return "";
   100	        }
   101	        boolean hasCountryCode = telephone.trim().startsWith("+");
   102	        String digits = telephone.replaceAll("\\D", "");
   103	        if (!hasCountryCode) {
   104	            if (digits.startsWith("0")) {
   105	                digits = digits.substring(1);
   106	            }
   107	            digits = DEFAULT_COUNTRY_CODE.substring(1) + digits;
   108	        }
   109	        return "+" + digits;
   110	    }
   111	}

